body.query:
  query DataUse($key: String!) {
    resource(id: $key) {
      ...ResourceRedirectDetails
      ... on DataUse {
        ...DataUsePage
      }
    }
  }

fragment ResourceRedirectDetails on Resource {
  __typename
  ... on Article {
    id
    title
    urlAlias
  }
  ... on Composition {
    id
    maybeTitle: title
    urlAlias
  }
  ... on DataUse {
    id
    title
  }
  ... on Document {
    id
    title
  }
  ... on MeetingEvent {
    id
    title
  }
  ... on News {
    id
    title
  }
  ... on Programme {
    id
    title
  }
  ... on GbifProject {
    id
    title
  }
  ... on Tool {
    id
    title
  }
}

fragment DataUsePage on DataUse {
  id
  title
  summary
  resourceUsed
  excerpt
  body
  primaryImage {
    ...ArticleBanner
  }
  primaryLink {
    label
    url
  }
  secondaryLinks {
    label
    url
  }
  countriesOfCoverage
  topics
  purposes
  audiences
  citation
  createdAt
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}
